#include <bits/stdc++.h>
using namespace std;

static bool adj[1001][1001];

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int S, T;
    cin >> S >> T;

    memset(adj, 0, sizeof(adj));

    for(int i = 0; i < T; i++){
        int x, y;
        cin >> x >> y;
        adj[x][y] = true;
        adj[y][x] = true;
    }

    int P;
    cin >> P;

    int possible = 0;

    for(int p = 0; p < P; p++){
        int N;
        cin >> N;
        int prev = -1, cur;
        bool ok = true;
        for(int i = 0; i < N; i++){
            cin >> cur;
            if(prev != -1 && !adj[prev][cur]) ok = false;
            prev = cur;
        }
        if(ok) possible++;
    }

    cout << possible << "\n";
    return 0;
}
